helpers.log('Starting Switch node');

const val = node.properties.inputField.value;
let rules = node.properties.routingRules.value;

helpers.log(`Input value: ${JSON.stringify(val)}`);

// Parse rules if it's a string (legacy JSON format)
if (typeof rules === 'string' && rules.trim()) {
  try {
    rules = JSON.parse(rules);
    helpers.log('Parsed legacy JSON format');
  } catch (e) {
    helpers.error(`Failed to parse routing rules: ${e.message}`);
    return { ...data, error: 'Invalid routing rules format', path: 'default' };
  }
}

// Validate that rules is an array
if (!Array.isArray(rules)) {
  helpers.error('Routing rules must be an array');
  return { ...data, error: 'Routing rules must be an array', path: 'default' };
}

helpers.log(`Evaluating ${rules.length} routing rule(s)`);

let path = 'default';

for (let i = 0; i < rules.length; i++) {
  const rule = rules[i];

  if (!rule.output || !rule.operator || rule.value === undefined) {
    helpers.warn(`Rule ${i + 1}: Missing required fields, skipping`);
    continue;
  }

  helpers.log(`Rule ${i + 1}: ${rule.operator} ${JSON.stringify(rule.value)} -> ${rule.output}`);

  let condition = false;

  switch (rule.operator) {
    case 'equals':
      condition = (val == rule.value);
      break;
    case 'not_equals':
      condition = (val != rule.value);
      break;
    case 'contains':
      condition = (val || '').toString().includes(rule.value);
      break;
    case 'greater_than':
      condition = Number(val) > Number(rule.value);
      break;
    case 'less_than':
      condition = Number(val) < Number(rule.value);
      break;
    default:
      helpers.warn(`Rule ${i + 1}: Unknown operator '${rule.operator}'`);
      break;
  }

  helpers.log(`Rule ${i + 1} condition: ${condition}`);

  if (condition) {
    path = rule.output;
    helpers.log(`Match found! Routing to: ${path}`);
    break;
  }
}

if (path === 'default') {
  helpers.log('No rules matched, using default path');
}

helpers.log('Switch node execution completed');

// IMPORTANT: Return path separately to ensure it's not overwritten by data
const result = typeof data === 'object' && data !== null ? { ...data } : { data };
result.path = path;

return result;
